				loadedConfig._version = this.version
				migrated = true
			}
			this.config = {
				_version: this.version,
				_credentials: new Map(Object.entries(loadedConfig._credentials ?? {})) as Map<Id, PersistentCredentials>,
				_scheduledAlarmUsers: loadedConfig._scheduledAlarmUsers ?? [],
				_themeId: loadedConfig._themeId ?? loadedConfig._theme ?? defaultThemeId,
				_language: loadedConfig._language ?? null,
				_defaultCalendarView: loadedConfig._defaultCalendarView ?? {},
